{
  "name": "AIBOX Face Detection",
  "sourceFamily": "AIBOX",
  "match": {
    "deviceId": "AIBOX-001"
  },
  "matchAll": [
    { "field": "raw.Events.Code", "operator": "eq", "values": ["FaceDetection"] }
  ],
  "mappings": [
    { "sourcePath": "Address",     "targetPath": "deviceId",     "required": true },
    { "sourcePath": "ChannelID",   "targetPath": "channelId",    "required": true },
    { "sourcePath": "Events.Code", "targetPath": "eventType",    "required": true }
  ],
  "classificationRules": [
    {
      "name": "blacklistCritical",
      "when": [
        { "field": "payload.listType", "operator": "eq", "values": ["3"] }
      ],
      "set": { "eventClass": "blacklist", "eventSeverity": "critical" },
      "order": 1
    }
  ],
  "deliveryTargets": [
    {
      "targetId": "{{targetId}}"
    }
  ],
  "dlq": {
    "enabled": true,
    "maxRetries": 3,
    "retryTimeoutSeconds": 60
  },
  "defaultLocale": "th",
  "messageTemplates": [
    {
      "key": "faceAlertTh",
      "channelType": "line",
      "locale": "th",
      "title": "[{{.eventSeverity}}] {{.eventType}}",
      "body": "Class: {{.eventClass}}\nDevice: {{.source.deviceId}}"
    }
  ]
}

{
  "name": "AIBOX Face Detection v2",
  "sourceFamily": "AIBOX",
  "mappings": [
    { "sourcePath": "Address",     "targetPath": "deviceId",     "required": true },
    { "sourcePath": "ChannelID",   "targetPath": "channelId",    "required": true },
    { "sourcePath": "Events.Code", "targetPath": "eventType",    "required": true },
    { "sourcePath": "Events.Data.Confidence", "targetPath": "confidence", "required": false }
  ]
}
